import{_ as r,o as t,c as o,a5 as a}from"./chunks/framework.DJo0M80U.js";const p=JSON.parse('{"title":"全局前置守卫","description":"你可以使用 router.beforeEach 注册一个 全局前置守卫 ： const router createRouter(\\\\{ ... \\\\}) router.beforeEach((to, from) \\\\ \\\\{ // ... // 返回 false 以取消导航 return。","frontmatter":{"title":"全局前置守卫","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","路由与状态管理"],"description":"你可以使用 router.beforeEach 注册一个 全局前置守卫 ： const router createRouter(\\\\{ ... \\\\}) router.beforeEach((to, from) \\\\ \\\\{ // ... // 返回 false 以取消导航 return。","sidebarWeight":39,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/vueRouter/导航守卫/全局前置守卫.md"},"headers":[],"relativePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/全局前置守卫.md","filePath":"posts/Vue系统教程/04-路由与状态管理/导航守卫/全局前置守卫.md"}'),n={name:"posts/Vue系统教程/04-路由与状态管理/导航守卫/全局前置守卫.md"};function s(c,e,u,i,f,l){return t(),o("div",null,[...e[0]||(e[0]=[a('<div><h1 id="全局前置守卫" tabindex="-1">全局前置守卫 <a class="header-anchor" href="#全局前置守卫" aria-label="Permalink to &quot;全局前置守卫&quot;">​</a></h1><blockquote><p>本节目标：理解“全局前置守卫”的核心思路，并能把它用于实际开发或面试表达。 你可以使用 router.beforeEach 注册一个<strong>全局前置守卫</strong>： const router = createRouter({ ... }) router.beforeEach((to, from) =&gt; { // ... // 返回 false 以取消导航 return false }) 当一个导航触发时，全局前置守卫按照创建顺序调用。守卫是异步解析执行，此时导航在所有守卫 resolve 完之前一直处于等待中。 每个守卫方法接收两个参数：</p></blockquote><ul><li>to: 即将要进入的目标 用一种标准化的方式</li><li>from: 当前导航正要离开的路由 用一种标准化的方式</li></ul><p>可以返回的值如下:</p><ul><li>false: 取消当前的导航。如果浏览器的 URL 改变了(可能是用户手动或者浏览器后退按钮)，那么 URL 地址会重置到 from 路由对应的地址。</li><li>一个路由地址: 通过一个路由地址跳转到一个不同的地址，就像你调用 router.push() 一样，你可以设置诸如 replace: true 或 name: &#39;home&#39; 之类的配置。当前的导航被中断，然后进行一个新的导航，就和 from 一样。</li></ul><p>router.beforeEach(async (to, from) =&gt; { if ( // 检查用户是否已登录 !isAuthenticated &amp;&amp; // ❗️ 避免无限重定向 to.name !== &#39;Login&#39; ) { // 将用户重定向到登录页面 return { name: &#39;Login&#39; } } }) 如果遇到了意料之外的情况，可能会抛出一个 Error。这会取消导航并且调用 router.onError() 注册过的回调。</p><p>如果什么都没有，undefined 或返回 true，则导航是有效的，并调用下一个导航守卫 以上所有都同 async 函数 和 Promise 工作方式一样： router.beforeEach(async (to, from) =&gt; { // canUserAccess() 返回 <code>true</code> 或 <code>false</code> const canAccess = await canUserAccess(to) if (!canAccess) return &#39;/login&#39; })</p><p>可选的第三个参数 next 在之前的 Vue Router 版本中，也是可以使用 第三个参数 next 的。这是一个常见的错误来源，可以通过 RFC 来消除错误。然而，它仍然是被支持的，这意味着你可以向任何导航守卫传递第三个参数。在这种情况下，确保 next 在任何给定的导航守卫中都被严格调用一次。它可以出现多于一次，但是只能在所有的逻辑路径都不重叠的情况下，否则钩子永远都不会被解析或报错。这里有一个在用户未能验证身份时重定向到/login的错误用例： // BAD router.beforeEach((to, from, next) =&gt; { if (to.name !== &#39;Login&#39; &amp;&amp; !isAuthenticated) next({ name: &#39;Login&#39; }) // 如果用户未能验证身份，则 <code>next</code> 会被调用两次 next() }) 下面是正确的版本: // GOOD router.beforeEach((to, from, next) =&gt; { if (to.name !== &#39;Login&#39; &amp;&amp; !isAuthenticated) next({ name: &#39;Login&#39; }) else next() })</p><p>全局解析守卫 你可以用 router.beforeResolve 注册一个全局守卫。这和 router.beforeEach 类似，因为它在 每次导航时都会触发，但是确保在导航被确认之前，同时在所有组件内守卫和异步路由组件被解析之后，解析守卫就被正确调用。这里有一个例子，确保用户可以访问自定义 meta 属性 requiresCamera 的路由： router.beforeResolve(async to =&gt; { if (to.meta.requiresCamera) { try { await askForCameraPermission() } catch (error) { if (error instanceof NotAllowedError) { // ... 处理错误，然后取消导航 return false } else { // 意料之外的错误，取消导航并把错误传给全局处理器 throw error } } } }) router.beforeResolve 是获取数据或执行任何其他操作（如果用户无法进入页面时你希望避免执行的操作）的理想位置。</p><p><strong>全局后置钩子</strong> 你也可以注册全局后置钩子，然而和守卫不同的是，这些钩子不会接受 next 函数也不会改变导航本身： router.afterEach((to, from) =&gt; { sendToAnalytics(to.fullPath) }) 它们对于分析、更改页面标题、声明页面等辅助功能以及许多其他事情都很有用。 它们也反映了 navigation failures 作为第三个参数： router.afterEach((to, from, failure) =&gt; { if (!failure) sendToAnalytics(to.fullPath) }) 了解更多关于 navigation failures 的信息在它的指南中。</p></div>',1)])])}const d=r(n,[["render",s]]);export{p as __pageData,d as default};
